import { Component, Element, Prop, State, Watch, h } from "@stencil/core";
import FormControlGroup from "../../functional-components/form-control/form-control-group";
import { hasSlot } from "../../utils/slot";

let id = 0;
/**
 * @since 0.0.10
 * @status experimental
 *
 * @description Switch group component that wraps a group of switches. It provides a label and help text for the group.
 *
 * @slot - The default slot where switch are placed.
 * @slot label - The switch group label. Required for proper accessibility.
 * @slot label-suffix - The switch group label-suffix.
 * @slot help-text - The radio group hepl-text.
 *
 * @part base - The component's base wrapper.
 * @part label - The label wrapper.
 * @part children - The wrapper of the default slot.
 * @part help-text - The help-text wrapper.
 * @part asterisk - The asterisk in the label.
 * @part legend - The legend element.
 */
@Component({
	tag: "hbr-switch-group",
	styleUrl: "switch-group.scss",
	shadow: true,
	formAssociated: true,
})
export class SwitchGroup {
	labelId = `radio-group-label-${++id}`;
	@Element() host: HTMLHbrSwitchGroupElement;
	@State() hasLabel = false;
	@State() hasHelpTextSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;

	/** Hides the fieldset and legend that the switch group. The label will still be read by screen readers. */
	@Prop() noFieldset = false;

	/** The switch group label. Required for proper accessibility. Alternatively, you can use the label slot. */
	@Prop() label = "";

	/** The switch group helpText. */
	@Prop() helpText = "";

	@Prop() helpTextId = "";

	@Prop() required = false;

	@Prop() disabled = false;

	@Prop() error = false;

	@Prop() size: "xsmall" | "small" | "medium" | "large" = "medium";

	/** direction of the switch group */
	@Prop() direction: "row" | "column" = "row";

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	handleSlotChange() {
		this.hasLabel = hasSlot(this.host, "label");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
	}

	render() {
		return (
			<FormControlGroup
				hasHelpTextSlot={this.hasHelpTextSlot}
				label={this.label}
				labelId={this.labelId}
				hasLabelSlot={this.hasLabel}
				hasError={this.error}
				size={this.size}
				direction={this.direction}
				helpTextId={this.helpTextId}
				helpText={this.helpText}
				isRequired={this.required}
				isDisabled={this.disabled}
				noFieldset={this.noFieldset}
				role={"group"}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
			>
				<slot />
			</FormControlGroup>
		);
	}
}
